CREATE SCHEMA IF NOT EXISTS platform_reference;
CREATE TABLE platform_reference.languages(code text PRIMARY KEY CHECK(code~'^[a-z]{2,3}$'),name_key text NOT NULL UNIQUE,active boolean NOT NULL);
CREATE TABLE platform_reference.currencies(code char(3) PRIMARY KEY CHECK(code~'^[A-Z]{3}$'),name_key text NOT NULL UNIQUE,minor_unit integer NOT NULL CHECK(minor_unit BETWEEN 0 AND 9),active boolean NOT NULL);
CREATE TABLE platform_reference.countries(code char(2) PRIMARY KEY CHECK(code~'^[A-Z]{2}$'),name_key text NOT NULL UNIQUE,calling_code text NOT NULL CHECK(calling_code~'^\+[1-9][0-9]{0,3}$'),default_language_code text NOT NULL REFERENCES platform_reference.languages(code),default_locale text NOT NULL,default_currency_code char(3) NOT NULL REFERENCES platform_reference.currencies(code),default_timezone text NOT NULL,active boolean NOT NULL);
CREATE TABLE platform_reference.country_languages(country_code char(2) NOT NULL REFERENCES platform_reference.countries(code),language_code text NOT NULL REFERENCES platform_reference.languages(code),is_default boolean NOT NULL,active boolean NOT NULL,PRIMARY KEY(country_code,language_code));
CREATE UNIQUE INDEX country_languages_one_active_default ON platform_reference.country_languages(country_code) WHERE is_default AND active;
CREATE FUNCTION platform_reference.assert_country_default_language() RETURNS trigger LANGUAGE plpgsql AS $$BEGIN IF NOT EXISTS(SELECT 1 FROM platform_reference.country_languages WHERE country_code=NEW.code AND language_code=NEW.default_language_code AND active AND is_default)THEN RAISE EXCEPTION 'country default language must be supported';END IF;RETURN NEW;END$$;
CREATE CONSTRAINT TRIGGER countries_default_language_supported AFTER INSERT OR UPDATE ON platform_reference.countries DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION platform_reference.assert_country_default_language();
CREATE FUNCTION platform_reference.assert_supported_default_after_relation_change() RETURNS trigger LANGUAGE plpgsql AS $$DECLARE affected_country char(2);BEGIN affected_country:=COALESCE(NEW.country_code,OLD.country_code);IF EXISTS(SELECT 1 FROM platform_reference.countries c WHERE c.code=affected_country AND NOT EXISTS(SELECT 1 FROM platform_reference.country_languages cl WHERE cl.country_code=c.code AND cl.language_code=c.default_language_code AND cl.active AND cl.is_default))THEN RAISE EXCEPTION 'country default language must remain supported';END IF;RETURN COALESCE(NEW,OLD);END$$;
CREATE CONSTRAINT TRIGGER country_languages_preserve_country_default AFTER INSERT OR UPDATE OR DELETE ON platform_reference.country_languages DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION platform_reference.assert_supported_default_after_relation_change();
